package T
  record Cx
    Real re;
    Real im;
  end Cx;

  function cabs
    input Cx c;
    output Real y;
  algorithm
    y := sqrt(c.re * c.re + c.im * c.im);
  end cabs;

  model M
    parameter Integer m = 2;
    Cx v[m];
    Real a[m] = cabs(v);        // vectorised call: array of records -> scalar-record function
    Real x(start = 1);
  equation
    der(x) = -x;
    for i in 1:m loop
      v[i].re = x * i;
      v[i].im = 0;
    end for;
  end M;
end T;
